private resolveArgs(): NativeParsedArgs {
		const host = synaraHost();
		if (host) { return host.args; }

if (!synaraHost()) {
	const code = new CodeMain();
	code.main();
}

const beforeQuitListener = () => {
	const host = synaraHost();
	if (host && !host.canQuit()) { return; }

const win = assertReturnsDefined(window.win);
synaraHost()?.onLifecycle(win, {
	check: () => window.isReady ? this.onBeforeUnloadWindowInRenderer(window, UnloadReason.QUIT) : Promise.resolve(true),
	unload: () => this.onWillUnloadWindowInRenderer(window, UnloadReason.QUIT),
	reload: () => window.reload()
});
windowListeners.add(Event.fromNodeEventEmitter<electron.Event>(win, 'close')(e => {
	const host = synaraHost();
	if (host?.isPrimary(window.id) && !host.canQuit()) { e.preventDefault(); return; }
	if (host?.isPrepared(window.id)) { return; }

session.defaultSession.setPermissionRequestHandler((webContents, permission, callback, details) => {
			const host = synaraHost();
			if (host?.isAgentContents(webContents)) { return host.requestAgentPermission(webContents, permission, callback, details); }

session.defaultSession.setPermissionCheckHandler((webContents, permission, _origin, details) => {
			const host = synaraHost();
			if (host?.isAgentContents(webContents)) { return host.checkAgentPermission(webContents, permission, _origin, details); }

contents.on('will-navigate', event => {
				const host = synaraHost();
				if (host && !host.ownsNativeContents(contents) && !this.auxiliaryWindowsMainService?.getWindowByWebContents(contents) && !contents.getURL().startsWith(`${Schemas.vscodeWebview}://`)) { return; }

contents.setWindowOpenHandler(details => {
				const host = synaraHost();
				if (host && !host.ownsNativeContents(contents) && !this.auxiliaryWindowsMainService?.getWindowByWebContents(contents)) { return { action: 'deny' }; }
